import { Schema as S } from "effect";
import * as Ui from "@foldkit/ui";

export const ToastPayload = S.Struct({
  title: S.String,
  maybeDescription: S.Option(S.String),
});
export type ToastPayload = typeof ToastPayload.Type;

export const Toast = Ui.Toast.make(ToastPayload);

export const {
  Added,
  DismissedToast,
  Entry,
  Message,
  Model,
  dismiss,
  dismissAll,
  init,
  show,
  update,
  view,
} = Toast;
export type Entry = typeof Entry.Type;
export type Message = typeof Message.Type;
export type Model = typeof Model.Type;
export type OutMessage = typeof Toast.OutMessage.Type;
export type InitConfig = Ui.Toast.InitConfig;
export type ShowInput = Ui.Toast.ShowInput<ToastPayload>;
export type UpdateReturn = ReturnType<typeof update>;

export const {
  DismissAfter,
  Dismissed,
  DismissedAll,
  ElapsedDuration,
  GotAnimationMessage,
  HoveredEntry,
  LeftEntry,
  Position,
  Variant,
} = Ui.Toast;
export type EntryHandlers = Ui.Toast.EntryHandlers;
export type Position = Ui.Toast.Position;
export type Variant = Ui.Toast.Variant;

export {
  closeButtonClasses,
  containerClasses,
  descriptionClasses,
  entryClasses,
  titleClasses,
  toastClasses,
  toastEntryView,
} from "./view";

import { Match as M, Option } from "effect";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import type { EntryHandlers, Variant } from "@foldkit/ui/toast";

import type { Entry } from "./index";

export const containerClasses = "gap-2 p-4";

export const entryClasses = "w-80";

export const toastClasses =
  "relative rounded-lg border bg-white p-3 pr-9 text-gray-900 shadow-sm transition data-[closed]:opacity-0 data-[enter]:translate-y-1 data-[leave]:translate-y-1 data-[transition]:duration-150 data-[transition]:ease-out";

export const titleClasses = "text-sm font-semibold";

export const descriptionClasses = "mt-0.5 text-sm text-gray-600";

export const closeButtonClasses =
  "absolute right-2 top-2 rounded-md p-1 text-gray-500 transition hover:bg-gray-100 hover:text-gray-950 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600";

const variantClasses = (variant: Variant): string =>
  M.value(variant).pipe(
    M.when("Info", () => "border-gray-300"),
    M.when("Success", () => "border-emerald-300 bg-emerald-50"),
    M.when("Warning", () => "border-amber-300 bg-amber-50"),
    M.when("Error", () => "border-red-300 bg-red-50"),
    M.exhaustive
  );

export const toastEntryView = (entry: Entry, handlers: EntryHandlers): Html => {
  const h = html();

  return h.div(
    [h.Class(`${toastClasses} ${variantClasses(entry.variant)}`)],
    [
      h.p([h.Class(titleClasses)], [entry.payload.title]),
      ...Option.match(entry.payload.maybeDescription, {
        onNone: () => [],
        onSome: (description) => [
          h.p([h.Class(descriptionClasses)], [description]),
        ],
      }),
      h.button(
        [
          ...handlers.dismiss,
          h.Type("button"),
          h.AriaLabel(`Dismiss ${entry.payload.title}`),
          h.Class(closeButtonClasses),
        ],
        ["x"]
      ),
    ]
  );
};

import { Match as M, Option, Schema as S } from "effect";
import { Command, Scene, Submodel } from "foldkit";
import * as Ui from "@foldkit/ui";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as Toast from "./index";
const primitiveEntryClassesKey = `${"entry"}${"Class"}${"Name"}` as const;
const primitiveContainerClassesKey = `${"container"}${"Class"}${"Name"}` as const;


const GotToastMessage = m("GotToastMessage", { message: Toast.Message });
const ClickedShowToast = m("ClickedShowToast");
const ClickedDismissAll = m("ClickedDismissAll");

const Model = S.Struct({
  toast: Toast.Model,
  status: S.String,
});
type Model = typeof Model.Type;

const Message = S.Union([GotToastMessage, ClickedShowToast, ClickedDismissAll]);
type Message = typeof Message.Type;

const initialModel: Model = {
  toast: Toast.init({ id: "registry-toast" }),
  status: "No notifications.",
};

const toAnimationMessage =
  (entryId: string) => (message: Ui.Animation.Message) =>
    GotToastMessage({
      message: Toast.GotAnimationMessage({ entryId, message }),
    });

const resolveEntryEnterAnimation = (entryId: string) =>
  Scene.Command.resolveAll(
    [
      Ui.Animation.RequestFrame,
      Ui.Animation.AdvancedAnimationFrame(),
      toAnimationMessage(entryId),
    ],
    [
      Ui.Animation.WaitForAnimationSettled({ id: entryId }),
      Ui.Animation.EndedAnimation(),
      toAnimationMessage(entryId),
    ]
  );

const resolveEntryLeaveAnimation = (entryId: string) =>
  Scene.Command.resolveAll(
    [
      Ui.Animation.RequestFrame,
      Ui.Animation.AdvancedAnimationFrame(),
      toAnimationMessage(entryId),
    ],
    [
      Ui.Animation.WaitForAnimationSettled({ id: entryId }),
      Ui.Animation.EndedAnimation(),
      toAnimationMessage(entryId),
    ]
  );

const updateToast = (
  model: Model,
  toast: Toast.Model,
  commands: readonly Command.Command<Toast.Message>[],
  maybeOutMessage: Option.Option<Toast.OutMessage>
): readonly [Model, readonly Command.Command<Message>[]] => {
  const status = Option.match(maybeOutMessage, {
    onNone: () => model.status,
    onSome: M.type<Toast.OutMessage>().pipe(
      M.tagsExhaustive({
        DismissedToast: ({ payload }) => `Dismissed: ${payload.title}`,
      })
    ),
  });

  return [
    evo(model, {
      toast: () => toast,
      status: () => status,
    }),
    Command.mapMessages(commands, (message) => GotToastMessage({ message })),
  ];
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotToastMessage: ({ message }) => {
        const [toast, commands, maybeOutMessage] = Toast.update(
          model.toast,
          message
        );

        return updateToast(model, toast, commands, maybeOutMessage);
      },
      ClickedShowToast: () => {
        const [toast, commands, maybeOutMessage] = Toast.show(model.toast, {
          variant: "Success",
          sticky: true,
          payload: {
            title: "Saved",
            maybeDescription: Option.some("Settings are up to date."),
          },
        });

        return updateToast(
          evo(model, { status: () => "Showing: Saved" }),
          toast,
          commands,
          maybeOutMessage
        );
      },
      ClickedDismissAll: () => {
        const [toast, commands, maybeOutMessage] = Toast.dismissAll(
          model.toast
        );

        return updateToast(model, toast, commands, maybeOutMessage);
      },
    })
  );

const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [],
    [
      h.button([h.Type("button"), h.OnClick(ClickedShowToast())], ["Show"]),
      h.button(
        [h.Type("button"), h.OnClick(ClickedDismissAll())],
        ["Dismiss all"]
      ),
      h.p([], [model.status]),
      h.submodel({
        slotId: model.toast.id,
        model: model.toast,
        view: Toast.view,
        viewInputs: {
          position: "BottomRight",
          entryToView: Toast.toastEntryView,
          [primitiveEntryClassesKey]: Toast.entryClasses,
          [primitiveContainerClassesKey]: Toast.containerClasses,
        },
        toParentMessage: (message) => GotToastMessage({ message }),
      }),
    ]
  );
});

describe("Toast registry view", () => {
  test("shows and marks toast entries for dismissal", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("region", { name: "Notifications" })).toExist(),
      Scene.click(Scene.role("button", { name: "Show" })),
      resolveEntryEnterAnimation("registry-toast-entry-0"),
      Scene.expect(Scene.role("status")).toExist(),
      Scene.expect(Scene.text("Saved")).toExist(),
      Scene.expect(Scene.text("Settings are up to date.")).toExist(),
      Scene.expect(Scene.text("Showing: Saved")).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss Saved" })),
      Scene.expect(Scene.role("status")).toHaveAttr("data-leave", ""),
      resolveEntryLeaveAnimation("registry-toast-entry-0"),
      Scene.expect(Scene.text("Dismissed: Saved")).toExist()
    );
  });
});
